class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('Capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now;

    this.tokens = capacity;
    this.lastRefillTime = this.now();
  }

  _refill() {
    const currentTime = this.now();
    const deltaSeconds = (currentTime - this.lastRefillTime) / 1000;

    // Saat geri giderse veya aynı kalsaydı hiçbir şey yapma
    if (deltaSeconds > 0) {
      const refillAmount = deltaSeconds * this.refillPerSecond;
      this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
      this.lastRefillTime = currentTime;
    } else if (currentTime > this.lastRefillTime) {
        // Bu durum aslında yukarıdaki deltaSeconds > 0 ile aynı, 
        // ancak mantıksal akış için belirtildi.
        this.lastRefillTime = currentTime;
    } else {
        // Zaman geri gitmişse, en büyük zaman referansını koru
        // (Zaten lastRefillTime'ı güncellemiyoruz)
    }
  }

  tryTake(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this.tokens;
  }

  msUntil(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.tokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity;
    }

    const needed = n - this.tokens;
    const msNeeded = (needed / this.refillPerSecond) * 1000;
    return Math.ceil(msNeeded);
  }
}

module.exports = { TokenBucket };

