# Test script to verify TokenBucket logic
test_script = """
const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function test() {
    console.log('Starting tests...');

    // 1. Temel işlevsellik ve kapasite
    let currentTime = 1000;
    const now = () => currentTime;
    const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });

    assert.strictEqual(bucket.available(), 10, 'Initial tokens should be capacity');

    // 2. tryTake başarılı mı?
    assert.strictEqual(bucket.tryTake(5), true, 'Should take 5 tokens');
    assert.strictEqual(bucket.available(), 5, 'Should have 5 tokens left');
    assert.strictEqual(bucket.tryTake(6), false, 'Should fail to take 6 tokens');
    assert.strictEqual(bucket.available(), 5, 'Available tokens should not change on failed tryTake');

    // 3. Zaman geçince dolum (refill)
    currentTime += 1000; // 1 saniye geçti
    assert.strictEqual(bucket.available(), 7, 'Should refill 2 tokens after 1s');

    // 4. msUntil
    assert.strictEqual(bucket.msUntil(1), 0, 'Should be 0 if tokens available');
    currentTime += 1000; // 1 saniye geçti -> jetonlar 9 oldu
    assert.strictEqual(bucket.msUntil(10), 500, 'Should need 500ms to get 10 tokens (needs 1 more token, 0.5s)');
    // 9 token var, 10 için 1 token lazım. 1 token / 2 per sec = 0.5s = 500ms.

    // 5. Saat geri giderse
    currentTime -= 5000; // Saati 5 saniye geri aldık
    assert.strictEqual(bucket.available(), 9, 'Tokens should not decrease if time goes back');
    currentTime += 100; // Küçük bir ileri hareket
    assert.strictEqual(bucket.available(), 9, 'Should not refill until time moves forward again');

    // 6. Sınır durumlar ve Infinity
    const emptyBucket = new TokenBucket({ capacity: 10, refillPerSecond: 0, now });
    assert.strictEqual(emptyBucket.msUntil(5), Infinity, 'Should be Infinity if refill rate is 0');

    const smallBucket = new TokenBucket({ capacity: 5, refillPerSecond: 1, now });
    assert.strictEqual(smallBucket.msUntil(10), Infinity, 'Should be Infinity if n > capacity');

    // 7. Hata kontrolü
    try {
        new TokenBucket({ capacity: -1, refillPerSecond: 1, now });
        assert.fail('Should throw RangeError for negative capacity');
    } catch (e) {
        assert.ok(e instanceof RangeError);
    }

    try {
        new TokenBucket({ capacity: 10, refillPerSecond: -1, now });
        assert.fail('Should throw RangeError for negative refill rate');
    } catch (e) {
        assert.ok(e instanceof RangeError);
    }

    try {
        bucket.tryTake(-1);
        assert.fail('Should throw RangeError for negative tryTake');
    } catch (e) {
        assert.ok(e instanceof RangeError);
    }

    console.log('All tests passed successfully!');
}

try {
    test();
} catch (err) {
    console.error('Test failed!');
    console.error(err);
    process.exit(1);
}
"""

with open('test_kova.js', 'w') as f:
    f.write(test_script)

result = subprocess.run(['node', 'test_kova.js'], capture_output=True, text=True)
print(result.stdout)
print(result.stderr)

if result.returncode != 0:
    sys.exit(1)

